import {
  CircleAlert,
  CircleCheck,
  Clock,
  ExternalLink,
  LoaderCircle,
} from "lucide-react";

import { t } from "@/i18n";
import { useState } from "react";

import {
  CardList,
  CardListItem,
  CardListMember,
  type CardListTone,
} from "@/ui/patterns/card-list";
import { ListPage } from "@/ui/patterns/list-page";
import { PageHeader } from "@/ui/patterns/page-header";
import { Badge } from "@/ui/shadcn/badge";
import { Button } from "@/ui/shadcn/button";
import { Progress } from "@/ui/shadcn/progress";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/ui/shadcn/tooltip";

import { sampleVideos } from "./list-page-example";

// registry:block card-list-example. Replace card content while retaining the shared spacing, surfaces and columns.

/** A card with members: one run whose parts are rows inside its border. */
function PipelineCardExample({ title }: { title: string }) {
  const a = t.activity;
  const [expanded, setExpanded] = useState(true);
  return (
    <CardListItem
      tone="primary"
      icon={
        <LoaderCircle
          role="img"
          aria-label={a.statusIcon.running}
          className="size-5 animate-spin text-primary"
        />
      }
      title={title}
      badge={<Badge variant="secondary">{a.kind.pipeline}</Badge>}
      detail={
        <span className="min-w-0 truncate">
          {a.pipeline.processing(a.kind.auto_tag, 1, 2)}
        </span>
      }
      time={a.time.justNow}
      timeShort={a.time.shortNow}
      expanded={expanded}
      onExpandedChange={setExpanded}
      toggleLabel={
        expanded
          ? { tooltip: a.pipeline.hideTasks, name: a.pipeline.hideTasksFor(title) }
          : { tooltip: a.pipeline.showTasks, name: a.pipeline.showTasksFor(title) }
      }
      members={
        <>
          <CardListMember
            icon={
              <CircleCheck
                role="img"
                aria-label={a.statusIcon.done}
                className="size-4 text-success"
              />
            }
            title={a.kind.import}
            detail={<span className="min-w-0 truncate">{a.result.done}</span>}
          />
          <CardListMember
            icon={
              <LoaderCircle
                role="img"
                aria-label={a.statusIcon.running}
                className="size-4 animate-spin text-primary"
              />
            }
            title={a.kind.auto_tag}
            detail={
              <>
                <Badge variant="soft">{a.pipeline.matches}</Badge>
                <span className="min-w-0 truncate">{a.result.running}</span>
              </>
            }
          />
        </>
      }
    />
  );
}

export function CardListExample() {
  const a = t.activity;
  const [first, second, third, fourth] = sampleVideos();
  const rows: {
    key: string;
    tone: CardListTone;
    icon: React.ReactNode;
    title: string;
    kind: string;
    detail: React.ReactNode;
    time: string;
    timeShort: string;
    open: boolean;
  }[] = [
    {
      key: "running",
      tone: "primary",
      icon: (
        <LoaderCircle
          role="img"
          aria-label={a.statusIcon.running}
          className="size-5 animate-spin text-primary"
        />
      ),
      title: first?.title ?? "",
      kind: a.kind.import,
      detail: (
        <>
          <span className="min-w-0 truncate">{a.stage.preview}</span>
          <span className="w-activity-bar shrink-0 max-lg:hidden">
            <Progress value={3} max={5} aria-label={a.stage.preview} />
          </span>
          <span className="shrink-0 text-primary tabular-nums">
            {a.result.progress(3, 5)}
          </span>
        </>
      ),
      time: a.time.justNow,
      timeShort: a.time.shortNow,
      open: true,
    },
    {
      key: "failed",
      tone: "destructive",
      icon: (
        <CircleAlert
          role="img"
          aria-label={a.statusIcon.attention}
          className="size-5 text-destructive"
        />
      ),
      title: second?.title ?? "",
      kind: a.kind.import,
      detail: (
        <span className="min-w-0 truncate text-destructive">
          {a.result.importFailed(a.stage.thumbnail, "")}
        </span>
      ),
      time: a.time.minutes(12),
      timeShort: a.time.shortMinutes(12),
      open: true,
    },
    {
      key: "warning",
      tone: "warning",
      icon: (
        <CircleAlert
          role="img"
          aria-label={a.statusIcon.attention}
          className="size-5 text-warning"
        />
      ),
      title: a.subject.pair(third?.title ?? "", fourth?.title ?? ""),
      kind: a.kind.version_judgement,
      detail: (
        <span className="min-w-0 truncate text-warning">{a.result.noConnection}</span>
      ),
      time: a.time.hours(2),
      timeShort: a.time.shortHours(2),
      open: false,
    },
    {
      key: "waiting",
      tone: "default",
      icon: (
        <Clock
          role="img"
          aria-label={a.statusIcon.waiting}
          className="size-5 text-muted-foreground"
        />
      ),
      title: fourth?.title ?? "",
      kind: a.kind.auto_tag,
      detail: <span className="min-w-0 truncate">{a.result.waiting}</span>,
      time: a.time.hours(3),
      timeShort: a.time.shortHours(3),
      open: false,
    },
    {
      key: "done",
      tone: "default",
      icon: (
        <CircleCheck
          role="img"
          aria-label={a.statusIcon.done}
          className="size-5 text-success"
        />
      ),
      title: third?.title ?? "",
      kind: a.kind.import,
      detail: <span className="min-w-0 truncate">{a.result.done}</span>,
      time: a.time.hours(5),
      timeShort: a.time.shortHours(5),
      open: true,
    },
  ];
  return (
    <ListPage header={<PageHeader title={a.title} />}>
      <CardList label={a.list}>
        <PipelineCardExample title={first?.title ?? ""} />
        {rows.map((row) => (
          <CardListItem
            key={row.key}
            tone={row.tone}
            icon={row.icon}
            title={row.title}
            badge={<Badge variant="secondary">{row.kind}</Badge>}
            detail={row.detail}
            time={row.time}
            timeShort={row.timeShort}
            actions={
              row.open && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button variant="ghost" size="icon-sm" aria-label={a.action.open}>
                      <ExternalLink aria-hidden="true" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>{a.action.open}</TooltipContent>
                </Tooltip>
              )
            }
          />
        ))}
      </CardList>
    </ListPage>
  );
}

import {
  EyeOff,
  Film,
  FolderPlus,
  LayoutGrid,
  List,
  Search,
  SlidersHorizontal,
  Tag,
} from "lucide-react";
import { type ReactNode, useState } from "react";

import { t } from "@/i18n";
import { CardGrid, type CardSize } from "@/ui/patterns/card-grid";
import { ListPage } from "@/ui/patterns/list-page";
import { LoadMoreRow } from "@/ui/patterns/load-more-row";
import { PageHeader } from "@/ui/patterns/page-header";
import { SelectionBar } from "@/ui/patterns/selection-bar";
import { Toolbar } from "@/ui/patterns/toolbar";
import { Button } from "@/ui/shadcn/button";
import { Checkbox } from "@/ui/shadcn/checkbox";
import { Input } from "@/ui/shadcn/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/ui/shadcn/select";
import { Slider } from "@/ui/shadcn/slider";
import { ToggleGroup, ToggleGroupItem } from "@/ui/shadcn/toggle-group";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/ui/shadcn/tooltip";
import {
  VideoThumbnail,
  VideoThumbnailDuration,
  VideoThumbnailMark,
} from "@/ui/VideoThumbnail";

// registry:block list-page-example. Replace sample data and cards; see web/registry/rules/patterns.md, List page.

const durations = ["49:10", "3:12", "12:48", "27:05", "1:02:33", "8:40", "15:20", "4:55"];

export function sampleVideos() {
  const p = t.designSystem.pattern;
  return Object.entries(p.videoTitles).map(([id, title], index) => ({
    id,
    title,
    meta: p.videoMeta(durations[index] ?? "", p.addedAgo(index + 1)),
    duration: durations[index] ?? "",
  }));
}

export function SampleVideoCard({
  title,
  meta,
  duration,
  selected,
  onSelectedChange,
}: {
  title: string;
  meta: string;
  duration: string;
  selected: boolean;
  onSelectedChange: (selected: boolean) => void;
}) {
  const p = t.designSystem.pattern;
  return (
    <article className="flex min-w-0 flex-col gap-2">
      <VideoThumbnail selected={selected}>
        <div className="flex size-full items-center justify-center text-muted-foreground">
          <Film aria-hidden="true" className="size-6" />
        </div>
        <VideoThumbnailDuration>{duration}</VideoThumbnailDuration>
        <VideoThumbnailMark corner="top-start">
          <Checkbox
            checked={selected}
            onCheckedChange={(checked) => {
              onSelectedChange(checked === true);
            }}
            aria-label={p.select(title)}
          />
        </VideoThumbnailMark>
      </VideoThumbnail>
      <div className="flex min-w-0 flex-col gap-0.5">
        <h2 className="truncate text-sm font-medium">{title}</h2>
        <p className="truncate text-xs text-muted-foreground">{meta}</p>
      </div>
    </article>
  );
}

/**
 * This demo substitutes for the shell top bar; real pages pass a TopBarPortal-wrapped toolbar to
 * ListPage.
 */
export function ExampleTopBar({ children }: { children: ReactNode }) {
  return (
    <div className="flex h-navbar items-center border-b border-border bg-navbar px-2 sm:px-3">
      {children}
    </div>
  );
}

export function ExampleToolbar({
  size = 1,
  onSizeChange,
}: {
  size?: CardSize;
  onSizeChange?: (size: CardSize) => void;
}) {
  const p = t.designSystem.pattern;
  const [view, setView] = useState("grid");
  const [sort, setSort] = useState("added");
  return (
    <Toolbar
      placement="topBar"
      search={
        <div className="relative">
          <Search
            aria-hidden="true"
            className="pointer-events-none absolute top-2 left-2 size-4 text-muted-foreground"
          />
          <Input
            type="search"
            aria-label={p.search}
            placeholder={p.search}
            className="h-8 pl-8"
          />
        </div>
      }
      view={[
        {
          id: "sort",
          label: p.sort,
          inlineFrom: "md",
          control: (
            <Select value={sort} onValueChange={setSort}>
              <SelectTrigger size="sm" aria-label={p.sort}>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="added">{p.sortAdded}</SelectItem>
                <SelectItem value="title">{p.sortTitle}</SelectItem>
                <SelectItem value="duration">{p.sortDuration}</SelectItem>
              </SelectContent>
            </Select>
          ),
        },
        {
          id: "view",
          label: p.view,
          inlineFrom: "lg",
          control: (
            <ToggleGroup
              type="single"
              variant="outline"
              size="sm"
              value={view}
              onValueChange={(value) => {
                if (value) setView(value);
              }}
              aria-label={p.view}
            >
              <IconToggle
                value="grid"
                label={p.grid}
                icon={<LayoutGrid aria-hidden="true" />}
              />
              <IconToggle
                value="list"
                label={p.list}
                icon={<List aria-hidden="true" />}
              />
            </ToggleGroup>
          ),
        },
        {
          id: "size",
          label: p.cardSize,
          inlineFrom: "xl",
          hideBelowSm: true,
          control: (
            <Slider
              aria-label={p.cardSize}
              min={0}
              max={3}
              step={1}
              value={[size]}
              onValueChange={([value]) => {
                onSizeChange?.((value ?? 1) as CardSize);
              }}
              className="w-zoom"
            />
          ),
        },
      ]}
      viewLabel={p.viewAndSort}
    >
      <Button variant="outline" size="sm">
        <SlidersHorizontal aria-hidden="true" />
        {p.filters}
      </Button>
    </Toolbar>
  );
}

function IconToggle({
  value,
  label,
  icon,
}: {
  value: string;
  label: string;
  icon: ReactNode;
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <ToggleGroupItem value={value} aria-label={label}>
          {icon}
        </ToggleGroupItem>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  );
}

export function ExampleHeader() {
  const p = t.designSystem.pattern;
  return (
    <PageHeader
      title={p.library}
      count={p.videos(128)}
      actions={
        <Button size="sm">
          <FolderPlus aria-hidden="true" />
          {p.addFolder}
        </Button>
      }
    />
  );
}

export function ListPageExample() {
  const p = t.designSystem.pattern;
  const videos = sampleVideos();
  const [size, setSize] = useState<CardSize>(1);
  const [selected, setSelected] = useState<ReadonlySet<string>>(
    () => new Set(["harbour", "market"]),
  );
  const toggle = (id: string, on: boolean) => {
    setSelected((current) => {
      const next = new Set(current);
      if (on) next.add(id);
      else next.delete(id);
      return next;
    });
  };
  return (
    <div className="flex flex-col">
      <ExampleTopBar>
        <ExampleToolbar size={size} onSizeChange={setSize} />
      </ExampleTopBar>
      <ListPage
        header={<ExampleHeader />}
        selectionBar={
          selected.size > 0 && (
            <SelectionBar
              count={p.selected(selected.size)}
              clearLabel={p.clearSelection}
              onClear={() => {
                setSelected(new Set());
              }}
            >
              <Button variant="ghost" size="sm">
                <Tag aria-hidden="true" />
                {p.addTag}
              </Button>
              <Button variant="ghost" size="sm">
                <EyeOff aria-hidden="true" />
                {p.hide}
              </Button>
            </SelectionBar>
          )
        }
      >
        <CardGrid size={size}>
          {videos.map((video) => (
            <SampleVideoCard
              key={video.id}
              title={video.title}
              meta={video.meta}
              duration={video.duration}
              selected={selected.has(video.id)}
              onSelectedChange={(on) => {
                toggle(video.id, on);
              }}
            />
          ))}
        </CardGrid>
        <LoadMoreRow status="loading" label={p.loadingMore} />
      </ListPage>
    </div>
  );
}
